proOverviewPlannerPrompt.responseSchema:
{
  "type": "object",
  "description": "Overview Planner output: user-facing response + optional plan overview",
  "required": [
    "uiDirective",
    "reasoningTrace"
  ],
  "properties": {
    "reasoningTrace": {
      "type": "string",
      "description": "Internal reasoning: mode determination, overview decisions, user signals, guardrails applied. NOT user-facing — for logging and audit."
    },
    "assistantText": {
      "type": "string",
      "description": "Execution log for chatHistory continuity — next-turn LLM reads this to know what changed structurally. MUST include: (1) overview state changes as `Overview: status=DRAFT|APPROVED|ABANDONED, overviewId=...`, (2) phase edits as `Phases: added=[...] removed=[...] modified=[...]`, (3) mode used as `Mode: GOAL_DECOMPOSITION|OVERVIEW_FEEDBACK|DIRECT_ANSWER`. NOT user-facing."
    },
    "thinkingText": {
      "type": "string",
      "description": "Short bridge message shown while the plan compiles. Emitted ONLY when planOverview.status = APPROVED. Must be high-level — do NOT reference specific steps, questions, or fields. Under 15 words.",
      "nullable": true
    },
    "uiDirective": {
      "type": "object",
      "description": "Screen composition instruction.",
      "properties": {
        "components": {
          "type": "array",
          "description": "Ordered list of components to render. Typically begins with RESPONSE_TEXT, followed by PLAN_PREVIEW_CARD when applicable.",
          "items": {
            "type": "object",
            "required": [
              "componentId"
            ],
            "properties": {
              "componentId": {
                "type": "string",
                "description": "Component ID: 'RESPONSE_TEXT' or 'PLAN_PREVIEW_CARD'."
              },
              "entityMeta": {
                "type": "object",
                "description": "Entity context for this component. Null for display-only components (RESPONSE_TEXT, PLAN_PREVIEW_CARD).",
                "nullable": true,
                "properties": {
                  "entityGroupId": {
                    "type": "string",
                    "description": "Entity group this component collects for (e.g., 'person_1', 'person_2', 'household_1')."
                  },
                  "relationshipToUser": {
                    "type": "string",
                    "enum": ["SELF", "SPOUSE", "PARENT", "CHILD", "HOUSEHOLD", "SIBLING", "OTHER"],
                    "description": "The entity's relationship to the primary user."
                  }
                }
              },
              "data": {
                "type": "string",
                "description": "The serialized JSON data payload. For RESPONSE_TEXT, must be {\"text\": \"...\"}. For PLAN_PREVIEW_CARD, must be null.",
                "nullable": true
              },
              "priority": {
                "type": "number",
                "description": "Display priority (1 = highest)."
              }
            }
          }
        }
      }
    },
    "planOverview": {
      "type": "object",
      "description": "High-level plan preview for user review. Emitted in MODE 1 (DRAFT) and MODE 2 (updated DRAFT or APPROVED). Null for MODE 3 (Q&A).",
      "nullable": true,
      "properties": {
        "overviewId": {
          "type": "string",
          "description": "Descriptive slug: 'ef-overview-v1'"
        },
        "status": {
          "type": "string",
          "enum": [
            "DRAFT",
            "APPROVED",
            "ABANDONED"
          ],
          "description": "DRAFT = under negotiation. APPROVED = user accepted, triggers plan compilation. ABANDONED = user exited this plan, resume normal routing."
        },
        "goal": {
          "type": "string",
          "description": "What we're planning for"
        },
        "scopeNote": {
          "type": "string",
          "description": "What the plan covers and what the user gets at the end. 1-2 sentences."
        },
        "approvalAction": {
          "type": "object",
          "description": "Approve CTA action object.",
          "required": [
            "guidanceMarker",
            "label",
            "actionType"
          ],
          "properties": {
            "guidanceMarker": {
              "type": "string",
              "enum": [
                "APPROVE_PLAN_OVERVIEW"
              ],
              "description": "The backend marker to handle this action"
            },
            "label": {
              "type": "string",
              "description": "Approve button text. Conversational. e.g., 'Looks good — let's start'"
            },
            "actionType": {
              "type": "string",
              "enum": [
                "GUIDED_COMPLETION"
              ],
              "description": "Tells the frontend which backend action to trigger when the user clicks."
            }
          }
        },
        "editAction": {
          "type": "object",
          "description": "Edit plan CTA action object.",
          "required": [
            "guidanceMarker",
            "label",
            "actionType"
          ],
          "properties": {
            "uiAction": {
              "type": "object",
              "required": [
                "uiActionType",
                "hintText"
              ],
              "properties": {
                "uiActionType": {
                  "type": "string",
                  "enum": [
                    "CHAT_BOX_FOCUS"
                  ],
                  "description": "Action to be take on ui when the user clicks on the edit action"
                },
                "hintText": {
                  "type": "string",
                  "description": "Text to be shown in the chat input box when user clicks on edit action"
                }
              }
            },
            "guidanceMarker": {
              "type": "string",
              "enum": [
                "EDIT_PLAN_OVERVIEW"
              ],
              "description": "The backend marker to handle this action"
            },
            "label": {
              "type": "string",
              "description": "Edit button text. Conversational. e.g., 'Suggest a change' or 'Edit plan'"
            },
            "actionType": {
              "type": "string",
              "enum": [
                "GUIDED_COMPLETION"
              ],
              "description": "Tells the frontend which backend action to trigger when the user clicks."
            }
          }
        },
        "phases": {
          "type": "array",
          "items": {
            "type": "object",
            "required": [
              "title",
              "description"
            ],
            "properties": {
              "title": {
                "type": "string",
                "description": "Phase title"
              },
              "description": {
                "type": "string",
                "description": "1-2 tight sentences: what happens in this phase and why it matters for the goal. Max ~20 words."
              }
            }
          }
        }
      }
    }
  }
}
